    while i < len(processed_pattern) and j < len(path_segments):
        if processed_pattern[i][0] == '**':
            # Push current positions and move to next pattern segment
            star_stack.append((i, j))
            i += 1
        elif match_segment(processed_pattern[i], path_segments[j]):
            i += 1
            j += 1
        else:
            if not star_stack:
                return False
            # Backtrack to last **
            i, j = star_stack.pop()
            j += 1

    # Match remaining path segments with **
    while j < len(path_segments):
        if not star_stack:
            return False
        i, j = star_stack.pop()
        j += 1

    # Match remaining pattern segments
    while i < len(processed_pattern):
        if processed_pattern[i][0] != '**':
            return False
        i += 1

    return True
